 public function ticker():array{$d=$this->get('/v2/tickers/'.rawurlencode((string)DELTA_SYMBOL));$r=$this->res($d);if(isset($r[0]))$r=$r[0];if(!is_array($r))throw new RuntimeException('Unexpected ticker response.');$last=sf($r['close']??$r['last_price']??$r['mark_price']??$r['spot_price']??0);if($last<=0)throw new RuntimeException('Ticker price missing. Verify DELTA_SYMBOL.');return ['symbol'=>$r['symbol']??DELTA_SYMBOL,'last'=>$last,'mark'=>sf($r['mark_price']??0),'spot'=>sf($r['spot_price']??0),'high'=>sf($r['high']??$r['high_price']??0),'low'=>sf($r['low']??$r['low_price']??0),'open'=>sf($r['open']??$r['open_price']??0),'volume'=>sf($r['volume']??$r['volume_24h']??0),'oi'=>sf($r['oi']??$r['open_interest']??0),'timestamp'=>time(),'source'=>'Delta Exchange REST','quality'=>'live'];}
 public function candles(string $resolution='',int $limit=200):array{$resolution=$resolution?:DELTA_CANDLE_RESOLUTION;$secs=['1m'=>60,'3m'=>180,'5m'=>300,'15m'=>900,'30m'=>1800,'1h'=>3600,'2h'=>7200,'4h'=>14400,'6h'=>21600,'1d'=>86400,'1w'=>604800];if(!isset($secs[$resolution]))throw new InvalidArgumentException('Unsupported candle resolution.');$limit=max(20,min(500,$limit));$end=time();$d=$this->get('/v2/history/candles',['resolution'=>$resolution,'symbol'=>DELTA_SYMBOL,'start'=>$end-$secs[$resolution]*$limit,'end'=>$end]);$r=$this->res($d);if(!is_array($r))throw new RuntimeException('Unexpected candle response.');$out=[];foreach($r as $c){if(!is_array($c))continue;$t=(int)($c['time']??$c['timestamp']??$c['t']??0);if($t>9999999999)$t=(int)($t/1000);$o=sf($c['open']??$c['o']??0);$h=sf($c['high']??$c['h']??0);$l=sf($c['low']??$c['l']??0);$cl=sf($c['close']??$c['c']??0);if($t>0&&min($o,$h,$l,$cl)>0)$out[]=['time'=>$t,'open'=>$o,'high'=>$h,'low'=>$l,'close'=>$cl,'volume'=>sf($c['volume']??$c['v']??0)];}usort($out,fn($a,$b)=>$a['time']<=>$b['time']);if(!$out)throw new RuntimeException('No usable candles returned for '.DELTA_SYMBOL.'.');return ['symbol'=>DELTA_SYMBOL,'resolution'=>$resolution,'candles'=>$out,'timestamp'=>time(),'source'=>'Delta Exchange REST','quality'=>'live'];}
 public function orderbook():array{$d=$this->get('/v2/l2orderbook/'.rawurlencode((string)DELTA_SYMBOL),['depth'=>10]);$r=$this->res($d);if(!is_array($r))throw new RuntimeException('Unexpected orderbook response.');$norm=function($levels){$out=[];if(!is_array($levels))return $out;foreach($levels as $x){if(!is_array($x))continue;$p=sf($x['price']??$x[0]??0);$s=sf($x['size']??$x['quantity']??$x[1]??0);if($p>0&&$s>=0)$out[]=['price'=>$p,'size'=>$s];}return array_slice($out,0,10);};$b=$norm($r['buy']??$r['bids']??[]);$a=$norm($r['sell']??$r['asks']??[]);if(!$a&&!$b)throw new RuntimeException('No usable orderbook levels returned.');return ['bids'=>$b,'asks'=>$a,'timestamp'=>time(),'source'=>'Delta Exchange REST','quality'=>'live'];}
